import unittest
from candidate import max_element

class TestMaxElement(unittest.TestCase):
    def test_single_element(self):
        self.assertEqual(max_element([42]), 42)

    def test_all_equal_elements(self):
        self.assertEqual(max_element([7, 7, 7, 7]), 7)

    def test_positive_integers(self):
        self.assertEqual(max_element([1, 2, 3, 4, 5]), 5)

    def test_negative_and_positive(self):
        self.assertEqual(max_element([-10, -5, 0, 5, 10]), 10)

    def test_floats_and_integers(self):
        self.assertEqual(max_element([3.14, 2, 3, 4.5]), 4.5)

    def test_strings(self):
        self.assertEqual(max_element(['apple', 'banana', 'cherry']), 'cherry')

    def test_boolean_values(self):
        self.assertEqual(max_element([False, False, True]), True)

    def test_mixed_numeric_types(self):
        self.assertEqual(max_element([1, 2.5, 3, 4.5]), 4.5)

    def test_large_list(self):
        big_list = list(range(-1000, 1001))
        self.assertEqual(max_element(big_list), 1000)

    def test_empty_list_raises_index_error(self):
        with self.assertRaises(IndexError):
            max_element([])

    def test_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            max_element(None)

    def test_list_with_none_element_raises_type_error(self):
        with self.assertRaises(TypeError):
            max_element([1, None, 3])

    def test_list_of_lists_raises_type_error(self):
        with self.assertRaises(TypeError):
            max_element([[1, 2], [3, 4]])

    def test_non_comparable_elements_raises_type_error(self):
        with self.assertRaises(TypeError):
            max_element([1, 'two', 3])

if __name__ == '__main__':
    unittest.main()
